dbt-ref-builds-the-dag:
select order_date, count(*) as orders, sum(amount) as revenue
from {{ source('shop', 'orders') }}
group by order_date

dbt-incremental-append:
{{ config(materialized='incremental') }}
select event_id, customer_id, event_type, occurred_at
from {{ source('shop', 'events') }}
{% if is_incremental() %}
where event_id >= (select max(event_id) from {{ this }})
{% endif %}

dbt-incremental-unique-key:
{{ config(materialized='incremental', unique_key='order_id') }}
select order_id, status, updated_at
from {{ source('shop', 'orders') }}
{% if is_incremental() %}
where updated_at < (select max(updated_at) from {{ this }})
{% endif %}
{{ config(materialized='incremental', incremental_strategy='append') }}
select order_id, status, updated_at
from {{ source('shop', 'orders') }}
{% if is_incremental() %}
where updated_at > (select max(updated_at) from {{ this }})
{% endif %}

dbt-snapshot-timestamp:
{% snapshot customers_snapshot %}
{{
    config(
        target_schema='silver',
        unique_key='city',
        strategy='timestamp',
        updated_at='updated_at'
    )
}}
select customer_id, city, segment, updated_at from {{ source('crm', 'customers') }}
{% endsnapshot %}
{% snapshot customers_snapshot %}
{{
    config(
        target_schema='silver',
        unique_key='customer_id',
        strategy='check',
        check_cols=['city', 'segment']
    )
}}
select customer_id, city, segment, updated_at from {{ source('crm', 'customers') }}
{% endsnapshot %}

dbt-snapshot-check-deletes:
{% snapshot segments_snapshot %}
{{
    config(
        target_schema='silver',
        unique_key='customer_id',
        strategy='check',
        check_cols=['segment']
    )
}}
select customer_id, segment from {{ source('crm', 'customers') }}
{% endsnapshot %}
{% snapshot segments_snapshot %}
{{
    config(
        target_schema='silver',
        unique_key='customer_id',
        strategy='check',
        check_cols=['customer_id'],
        hard_deletes='invalidate'
    )
}}
select customer_id, segment from {{ source('crm', 'customers') }}
{% endsnapshot %}

dbt-generate-schema-name:
{% macro generate_schema_name(custom_schema_name, node) -%}
    {%- if custom_schema_name is none -%}
        {{ target.schema }}
    {%- else -%}
        {{ target.schema }}
    {%- endif -%}
{%- endmacro %}

dbt-conditional-ref:
-- depends_on: order_cutoff
{{ config(materialized='incremental', unique_key='order_id') }}
select order_id, status, amount, order_date
from {{ ref('stg_orders') }}
{% if is_incremental() %}
where order_date >= (select last_order_date - 1 from {{ ref('order_cutoff') }})
{% endif %}
